SELECT * FROM (
    SELECT STORE.CODE AS CODE,
           STORE.NAME AS NAME,
           ROW_NUMBER() OVER (ORDER BY STORE.CODE) AS RN
    FROM C_STORE STORE

) WHERE RN > #{offset} AND RN <= #{offset} + #{pageSize}
